(()=>{'use strict';let data,currentBranch=null,selectedJob=null;const $=x=>document.getElementById(x),stages=['LEADS','APPOINTMENTS','INSPECTIONS','SCOPES','APPROVALS','PRODUCTION_READY','PRODUCTION','QC','CLOSEOUT'],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bad=j=>j.governance!=='ESTABLISHED'||j.flag;function branchJobs(b){return data.jobs.filter(j=>j.branch===b)}function count(a,f){return a.filter(f).length}
function renderBridge(){let a=data.jobs,flags=a.filter(bad).sort((x,y)=>(x.priority==='CRITICAL'?-2:x.priority==='HIGH'?-1:0)-(y.priority==='CRITICAL'?-2:y.priority==='HIGH'?-1:0)||y.ageHours-x.ageHours);$('metrics').innerHTML=[['Active jobs',a.length],['Production ready',count(a,j=>j.stage==='PRODUCTION_READY'&&j.governance==='ESTABLISHED')],['Need evidence',count(a,j=>j.governance==='UNPROVEN')],['Conflicts / blocked',count(a,j=>['CONFLICTING','NEGATED'].includes(j.governance))]].map(x=>'<div class="metric"><span class="muted">'+x[0]+'</span><b>'+x[1]+'</b></div>').join('');$('branches').innerHTML=data.branches.map(b=>{let j=branchJobs(b),f=j.filter(bad);return '<button class="branchCard" data-branch="'+b+'"><strong>'+b+'</strong><div class="branchStats"><span>'+j.length+' jobs</span><span>'+f.length+' flags</span><span>'+count(j,x=>x.governance==='CONFLICTING')+' conflicts</span><span>'+count(j,x=>x.governance==='NEGATED')+' blocked</span></div></button>'}).join('');document.querySelectorAll('[data-branch]').forEach(b=>b.onclick=()=>openBranch(b.dataset.branch));$('flags').innerHTML=flags.slice(0,8).map(j=>'<div class="flag"><div><b>'+esc(j.id)+' · '+esc(j.branch)+'</b><span class="muted">'+esc(j.flag||j.governance)+'</span></div><span class="'+j.priority+'">'+j.priority+'</span></div>').join('')}
function openBranch(b){currentBranch=b;selectedJob=null;$('branchTitle').textContent=b+' Branch';$('overlay').classList.add('open');showFront();renderBranch()}function renderBranch(){let a=branchJobs(currentBranch);$('workflow').innerHTML=stages.map(s=>'<div class="stage"><b>'+count(a,j=>j.stage===s)+'</b><span>'+s.replaceAll('_',' ')+'</span></div>').join('');$('jobs').innerHTML=a.map(j=>'<article class="job"><div class="eyebrow">'+esc(j.stage.replaceAll('_',' '))+'</div><h3>'+esc(j.id)+'</h3><p class="muted">'+esc(j.customer)+'</p><p class="'+j.governance+'"><b>'+({ESTABLISHED:'Ready',UNPROVEN:'Still needed',CONFLICTING:'Needs review',NEGATED:'Blocked'}[j.governance])+'</b></p>'+(j.flag?'<p>'+esc(j.flag)+'</p>':'')+'<button class="btn" data-select="'+j.id+'">Select for action</button> <a href="/prototypes/evan-job-stage/?job='+encodeURIComponent(j.id)+'">Open Job Stage →</a></article>').join('');document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selectedJob=data.jobs.find(j=>j.id===b.dataset.select);showBack()})}
function showFront(){$('front').classList.add('active');$('back').classList.remove('active');$('flip').textContent='Flip to actions'}function showBack(){$('front').classList.remove('active');$('back').classList.add('active');$('flip').textContent='Flip to operations';let j=selectedJob;$('receipt').innerHTML=j?'<b>Selected:</b> '+esc(j.id)+' · '+esc(j.flag||j.governance)+'<br>Choose a governed action.':'No job selected. Return to operations and select a job or flag.'}
$('flip').onclick=()=> $('front').classList.contains('active')?showBack():showFront();$('close').onclick=()=>{$('overlay').classList.remove('open');selectedJob=null};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{if(!selectedJob){$('receipt').textContent='Select a job on the front face before creating an action.';return}let action=b.dataset.action,expect=action==='SET_EXPECTATION'?'Required evidence/state must be established at next governance check.':'Resolution evidence required before governed progression.';$('receipt').innerHTML='<b>SYNTHETIC ACTION RECEIPT</b><br>Branch: '+esc(currentBranch)+'<br>Job: '+esc(selectedJob.id)+'<br>Issue: '+esc(selectedJob.flag||selectedJob.governance)+'<br>Action: '+esc(action.replaceAll('_',' '))+'<br>Disposition: '+(['CONFLICTING','NEGATED','UNPROVEN'].includes(selectedJob.governance)?'HOLD / RESOLVE BEFORE PROGRESSION':'MANAGEMENT FOLLOW-UP')+'<br>Next expectation: '+esc(expect)+'<br><span class="muted">Demo receipt only · no external message or task sent.</span>'});
fetch('./data-v1.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('DATA_LOAD_'+r.status);return r.json()}).then(x=>{data=x;renderBridge()}).catch(e=>{$('flags').innerHTML='<p class="CRITICAL">Operating data failed to load.</p>';console.error(e)})})();